UPDATE companies SET description='Midwest Medical Resources, Inc. is based in Overland Park, Kansas, and was founded in 2005. The company operates as a medical surgical sales agency with a focus on orthopedics. Ed Lewis is identified as a co‑founder, while John Tarantino serves as chief executive officer and Craig Dawson as chief operating officer.

The firm represents a portfolio of orthopedic devices and bracing products from manufacturers such as DJO Surgical and DonJoy. Its featured lines include the DonJoy VersaROM hip brace, the Empowr Partial Knee system, the AltiVate Anatomic shoulder system, and the A22 custom titanium knee brace. Midwest Medical’s sales team covers the entire Midwest region, providing surgical solutions and rehabilitation products to healthcare providers.

Midwest Medical states that its differentiators are a sales force trained on both its own and competitive product lines, a strategic consulting approach aimed at long‑term solutions, a service model that positions associates as an extension of the client’s team, and a local presence that enables rapid response to urgent needs.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Medical device sales representation", "Orthopedic product distribution", "Surgical solution consulting", "Bracing and rehabilitation product sales"], "industries": ["Orthopedics", "Medical surgical", "Bracing and rehabilitation", "Healthcare"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Sales team trained on both own and competitive product lines", "Strategic consulting for long-term solutions", "Local representatives for rapid response", "Focus on orthopedic surgical solutions and bracing"], "facts_used": ["Founded in 2005 -> /about", "Headquarters Overland Park, Kansas -> db", "Co-founder Ed Lewis -> /about", "CEO John Tarantino -> /about", "COO Craig Dawson -> /about", "Sales agency focus on orthopedics -> /about", "Serves entire Midwest -> /about", "Product lines: DonJoy VersaROM Hip, Empowr Partial Knee, AltiVate Anatomic Shoulder, A22 Custom Knee Brace -> /", "Philosophy: Patient Care is Key, Strategic Thinking, Stellar Service, Local -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We are a premier medical surgical sales agency with a focus on orthopedics", "founded_year": "2005", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/midwest-medical-resources/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='midwest-medical-resources-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Midwest Metal Products has operated from Cedar Rapids, Iowa since its founding in 1964. The company began as a precision metal fabrication shop and has grown into a full-service manufacturer serving aerospace, electrical, and medical markets.

The facility houses a range of metal fabrication processes including CNC punching, laser cutting, forming, welding (steel, stainless steel, and aluminum), hardware insertion, chromate conversion chem-film coating, silk-screening, press brake forming, turret/laser cutting, assembly, riveting, painting, and powder coating. Equipment includes high-speed EML turret/lasers with automated loading, a complete line of press brakes with three-axis computer controls and HDS machines, 12 automated and manual hardware insertion machines, and a FabriVISION® laser scanning system for flat layout verification. The company emphasizes single-source manufacturing from design through finishing.

Midwest Metal Products serves the aerospace industry as a Collins Aerospace Mechanical Supplier of the Year (2025), supplying commercial, defense, and private aviation programs. It also fabricates electronic enclosures and brackets for the electrical sector and produces components for medical equipment manufacturers, adhering to strict industry standards.

The company highlights its single-source manufacturing model, corrosion-resistant chem-film line, FabriVISION® scanning for first-article validation, and responsive customer service with flexible production capacity as key differentiators. Its commitment to quality, service, and on-time delivery is stated as paramount for every order.', certifications=ARRAY['AS9100','NADCAP','ITAR','ISO9001']::text[], profile='{"capabilities": ["CNC punching", "Laser cutting", "Forming", "Welding (steel, stainless steel, aluminum)", "Hardware insertion", "Chromate conversion chem-film coating", "Silk-screening", "Press brake forming", "Turret/laser cutting", "Assembly", "Riveting", "Painting", "Powder coating", "FabriVISION laser scanning"], "industries": ["Aerospace", "Electrical", "Medical"], "materials": ["Steel", "Stainless steel", "Aluminum"], "equipment": ["HDS press brakes", "EML turret/lasers", "Automated and manual hardware insertion machines (12)", "FabriVISION laser scanning system", "Chromate conversion chem-film line"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Single-source manufacturing with in-house silk-screening", "FabriVISION\u00ae high-speed laser scanning for flat layout authentication", "Chromate conversion chem-film line for corrosion-resistant coatings", "12 high-tech automated and manual hardware insertion machines", "High-speed EML turret/lasers with automated loading/unloading"], "facts_used": ["Founded 1964 -> db, homepage", "Headquarters Cedar Rapids, Iowa -> db, homepage", "Certifications AS9100, NADCAP, ITAR, ISO9001 -> db", "Capabilities: CNC punching, laser cutting, forming, welding, hardware insertion, chem-film, silk-screening, press brakes, turret/lasers, assembly, riveting, painting, powder coating, FabriVISION scanning -> homepage", "Industries: Aerospace, Electrical, Medical -> homepage", "Equipment: HDS machines, EML turret/lasers, 12 insertion machines, FabriVISION, chem-film line -> homepage", "Materials: steel, stainles